            built[i]?.let { return it }
            val table = when (theme) {
                PaletteTheme.Terracotta -> if (dark) PaletteTables.TERRACOTTA_DARK else PaletteTables.TERRACOTTA_LIGHT
                PaletteTheme.Sage -> if (dark) PaletteTables.SAGE_DARK else PaletteTables.SAGE_LIGHT
                PaletteTheme.Lavender -> if (dark) PaletteTables.LAVENDER_DARK else PaletteTables.LAVENDER_LIGHT
